        let (mut m, _) = fixture();
        for p in &mut m.payload {
            p.bytes = 0;
        }
        m.payload[0].bytes = u64::MAX;
        assert_eq!(validate_manifest_structure(&m), Ok(()));
        m.payload[1].bytes = 1;
        assert_eq!(validate_manifest_structure(&m), Err(AcquisitionError::Size));
