    {
      "term": "Corpus bundle",
      "definition": "The selected raw text and metadata payloads together with their manifest. In this synthetic example, two sources share one license payload and one attribution payload."
    },
    {
      "term": "Source provenance",
      "definition": "The record connecting selected corpus content to its source revision, provenance reference, license text and attribution. Matching those claims does not establish that they are true or grant permission."
    },
    {
      "term": "Canonical manifest",
      "definition": "A complete corpus record with one fixed byte representation, including content IDs, roles, counts, digests and provenance. The verifier rejects different formatting or ordering rather than silently rewriting it."
    },
    {
      "term": "Dataset artifact identity",
      "definition": "The SHA-256 digest of the complete canonical manifest. It identifies the record through its provenance and payload digests; supplied payload bytes still need verification. It is not a signature or permission certificate."
    },
    {
      "term": "Content ID",
      "definition": "A logical name for one payload in the selected corpus record. A source uses that name to refer to content; adapters choose how to retrieve or store it. The name is not a required filename or URL."
    },
    {
      "term": "Raw held-out source",
      "definition": "The separate raw text source selected outside the raw training source. Its name does not define the final validation or test split, which is constructed later."
    }
  ]
